#[derive(Debug, Clone, PartialEq, Default)] pub enum AvailabilityStrategy { #[default] All, TilingScheme { minimum_level: u32, maximum_level: u32, }, LayerJson, } #[derive(Debug, Clone)] pub struct CesiumTerrainProvider { pub url: String, pub request_vertex_normals: bool, pub request_water_mask: bool, pub availability: AvailabilityStrategy, pub credit: Option<String>, } impl CesiumTerrainProvider { pub fn new(url: impl Into<String>) -> Self { Self { url: url.into(), request_vertex_normals: false, request_water_mask: false, availability: AvailabilityStrategy::All, credit: None, } } pub fn with_vertex_normals(mut self) -> Self { self.request_vertex_normals = true; self } pub fn with_water_mask(mut self) -> Self { self.request_water_mask = true; self } pub fn get_tile_url(&self, level: u32, x: u32, y: u32) -> String { let base = self.url.trim_end_matches('/'); let mut url = format!("{}/{}/{}/{}.terrain", base, level, x, y); let mut params = Vec::new(); if self.request_vertex_normals { params.push("extensions=octvertexnormals"); } if self.request_water_mask { params.push("extensions=watermask"); } if !params.is_empty() { url.push('?'); url.push_str(&params.join("&")); } url } pub fn get_layer_json_url(&self) -> String { let base = self.url.trim_end_matches('/'); format!("{}/layer.json", base) } pub fn is_available(&self, level: u32) -> bool { match &self.availability { AvailabilityStrategy::All => true, AvailabilityStrategy::TilingScheme { minimum_level, maximum_level, } => level >= *minimum_level && level <= *maximum_level, AvailabilityStrategy::LayerJson => true, } } } #[derive(Debug, Clone, Default)] pub struct EllipsoidTerrainProvider; impl EllipsoidTerrainProvider { pub fn new() -> Self { Self } pub fn get_height(&self, _longitude: f64, _latitude: f64) -> f64 { 0.0 } } #[derive(Debug, Clone)] pub struct HeightmapTerrainProvider { pub url: String, pub width: u32, pub height: u32, pub file_extension: String, pub minimum_level: u32, pub maximum_level: u32, pub credit: Option<String>, } impl HeightmapTerrainProvider { pub fn new(url: impl Into<String>) -> Self { Self { url: url.into(), width: 65, height: 65, file_extension: "terrain".to_string(), minimum_level: 0, maximum_level: 25, credit: None, } } pub fn with_dimensions(mut self, width: u32, height: u32) -> Self { self.width = width; self.height = height; self } pub fn get_tile_url(&self, level: u32, x: u32, y: u32) -> String { let base = self.url.trim_end_matches('/'); format!( "{}/{}/{}/{}.{}", base, level, x, y, self.file_extension ) } pub fn is_available(&self, level: u32) -> bool { level >= self.minimum_level && level <= self.maximum_level } } #[derive(Debug, Clone)] pub struct VrTheWorldTerrainProvider { pub url: String, pub credit: Option<String>, } impl VrTheWorldTerrainProvider { pub fn new(url: impl Into<String>) -> Self { Self { url: url.into(), credit: None, } } pub fn get_tile_url(&self, level: u32, x: u32, y: u32) -> String { let base = self.url.trim_end_matches('/'); format!("{}/{}/{}/{}.tif", base, level, x, y) } } #[derive(Debug, Clone, Default)] pub struct TerrainLayerConfig { pub format: String, pub min_level: u32, pub max_level: u32, pub has_vertex_normals: bool, pub has_water_mask: bool, pub projection: String, pub bounds: Option<[f64; 4]>, } impl TerrainLayerConfig { pub fn from_json(json: &str) -> Result<Self, String> { let mut config = Self::default(); if let Some(format) = extract_json_string(json, "format") { config.format = format; } if let Some(min) = extract_json_number(json, "minLevel") { config.min_level = min as u32; } if let Some(max) = extract_json_number(json, "maxLevel") { config.max_level = max as u32; } if let Some(proj) = extract_json_string(json, "projection") { config.projection = proj; } config.has_vertex_normals = json.contains("octvertexnormals"); config.has_water_mask = json.contains("watermask"); Ok(config) } } fn extract_json_string(json: &str, key: &str) -> Option<String> { let pattern = format!("\"{}\"", key); let start = json.find(&pattern)? + pattern.len(); let colon = json[start..].find(':')? + start; let quote_start = json[colon..].find('"')? + colon + 1; let quote_end = json[quote_start..].find('"')? + quote_start; Some(json[quote_start..quote_end].to_string()) } fn extract_json_number(json: &str, key: &str) -> Option<f64> { let pattern = format!("\"{}\"", key); let start = json.find(&pattern)? + pattern.len(); let colon = json[start..].find(':')? + start; let value_start = colon + 1; let remaining = json[value_start..].trim_start(); let end = remaining .find(|c: char| !c.is_ascii_digit() && c != '.' && c != '-' && c != '+' && c != 'e' && c != 'E') .unwrap_or(remaining.len()); remaining[..end].parse().ok() } #[derive(Debug, Clone)] pub enum TerrainProviderKind { Cesium(CesiumTerrainProvider), Ellipsoid(EllipsoidTerrainProvider), Heightmap(HeightmapTerrainProvider), VrTheWorld(VrTheWorldTerrainProvider), } #[derive(Debug, Clone)] pub struct TerrainProviderDescriptor { pub kind: TerrainProviderKind, pub tiling_scheme: crate::tiling_scheme::TilingScheme, pub has_vertex_normals: bool, pub has_water_mask: bool, pub maximum_level: u32, } impl TerrainProviderDescriptor { pub fn cesium(provider: CesiumTerrainProvider, max_level: u32) -> Self { Self { has_vertex_normals: provider.request_vertex_normals, has_water_mask: provider.request_water_mask, kind: TerrainProviderKind::Cesium(provider), tiling_scheme: crate::tiling_scheme::TilingScheme::geographic(), maximum_level: max_level, } } pub fn ellipsoid() -> Self { Self { kind: TerrainProviderKind::Ellipsoid(EllipsoidTerrainProvider), tiling_scheme: crate::tiling_scheme::TilingScheme::geographic(), has_vertex_normals: false, has_water_mask: false, maximum_level: 0, } } pub fn heightmap(provider: HeightmapTerrainProvider) -> Self { let max_level = provider.maximum_level; Self { kind: TerrainProviderKind::Heightmap(provider), tiling_scheme: crate::tiling_scheme::TilingScheme::geographic(), has_vertex_normals: false, has_water_mask: false, maximum_level: max_level, } } pub fn get_tile_url(&self, level: u32, x: u32, y: u32) -> Option<String> { match &self.kind { TerrainProviderKind::Cesium(p) => Some(p.get_tile_url(level, x, y)), TerrainProviderKind::Ellipsoid(_) => None, TerrainProviderKind::Heightmap(p) => Some(p.get_tile_url(level, x, y)), TerrainProviderKind::VrTheWorld(p) => Some(p.get_tile_url(level, x, y)), } } pub fn is_available(&self, level: u32) -> bool { level <= self.maximum_level } } #[derive(Debug, Clone, Copy, PartialEq)] pub struct SampledHeight { pub longitude: f64, pub latitude: f64, pub height: Option<f64>, } #[derive(Debug, Clone)] pub struct HeightmapSampleParams<'a> { pub heightmap: &'a [f64], pub grid_width: usize, pub grid_height: usize, pub tile_west: f64, pub tile_south: f64, pub tile_east: f64, pub tile_north: f64, pub min_height: f64, pub max_height: f64, } pub fn sample_height_bilinear( params: &HeightmapSampleParams<'_>, longitude: f64, latitude: f64, ) -> Option<f64> { let heightmap = params.heightmap; let grid_width = params.grid_width; let grid_height = params.grid_height; if heightmap.len() < grid_width * grid_height { return None; } if longitude < params.tile_west || longitude > params.tile_east || latitude < params.tile_south || latitude > params.tile_north { return None; } let fx = (longitude - params.tile_west) / (params.tile_east - params.tile_west) * (grid_width - 1) as f64; let fy = (params.tile_north - latitude) / (params.tile_north - params.tile_south) * (grid_height - 1) as f64; let x0 = (fx as usize).min(grid_width - 2); let y0 = (fy as usize).min(grid_height - 2); let x1 = x0 + 1; let y1 = y0 + 1; let tx = fx - x0 as f64; let ty = fy - y0 as f64; let h00 = heightmap[y0 * grid_width + x0]; let h10 = heightmap[y0 * grid_width + x1]; let h01 = heightmap[y1 * grid_width + x0]; let h11 = heightmap[y1 * grid_width + x1]; let h = h00 * (1.0 - tx) * (1.0 - ty) + h10 * tx * (1.0 - ty) + h01 * (1.0 - tx) * ty + h11 * tx * ty; Some(h.clamp(params.min_height, params.max_height)) } #[derive(Debug, Clone)] pub struct QuantizedSampleParams<'a> { pub quantized_vertices: &'a [u16], pub vertex_count: usize, pub tile_west: f64, pub tile_south: f64, pub tile_east: f64, pub tile_north: f64, pub min_height: f64, pub max_height: f64, } pub fn sample_height_quantized( params: &QuantizedSampleParams<'_>, longitude: f64, latitude: f64, ) -> Option<f64> { let quantized_vertices = params.quantized_vertices; let vertex_count = params.vertex_count; if quantized_vertices.len() < vertex_count * 3 { return None; } let u_query = ((longitude - params.tile_west) / (params.tile_east - params.tile_west) * 32767.0) as u16; let v_query = ((latitude - params.tile_south) / (params.tile_north - params.tile_south) * 32767.0) as u16; let mut best_dist = u32::MAX; let mut best_height = 0u16; for i in 0..vertex_count { let u = quantized_vertices[i]; let v = quantized_vertices[vertex_count + i]; let h = quantized_vertices[vertex_count * 2 + i]; let du = (u as i32 - u_query as i32).unsigned_abs(); let dv = (v as i32 - v_query as i32).unsigned_abs(); let dist = du + dv; if dist < best_dist { best_dist = dist; best_height = h; } } let t = best_height as f64 / 32767.0; Some(params.min_height + t * (params.max_height - params.min_height)) } #[derive(Debug, Clone)] pub struct ArcGisTerrainProvider { pub url: String, pub use_https: bool, pub tile_width: u32, pub tile_height: u32, pub maximum_level: u32, pub credit: Option<String>, } impl ArcGisTerrainProvider { pub fn new(url: impl Into<String>) -> Self { Self { url: url.into(), use_https: true, tile_width: 256, tile_height: 256, maximum_level: 23, credit: None, } } pub fn with_credit(mut self, credit: impl Into<String>) -> Self { self.credit = Some(credit.into()); self } pub fn get_tile_url(&self, level: u32, x: u32, y: u32) -> String { format!( "{}/tile/{}/{}/{}", self.url.trim_end_matches('/'), level, y, x ) } } #[derive(Debug, Clone, PartialEq)] pub struct GoogleEarthEnterpriseTerrainProvider { pub url: String, pub path: Str